def minimumDeleteSum(s1, s2):
    m, n = len(s1), len(s2)
    prev = [0] * (n + 1)
    for i in range(1, m + 1):
        cur = [0] * (n + 1)
        a = s1[i - 1]
        w = ord(a)
        for j in range(1, n + 1):
            if a == s2[j - 1]:
                cur[j] = prev[j - 1] + w
            else:
                cur[j] = cur[j - 1] if cur[j - 1] > prev[j] else prev[j]
        prev = cur
    total = sum(map(ord, s1)) + sum(map(ord, s2))
    return total - 2 * prev[n]
